// ── Issue #666: Multi-Signature Attestation Workflow ─────────────────────────

/// Sensitivity level for a credential type, controlling multi-sig requirements.
#[contracttype]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u32)]
pub enum CredentialSensitivity {
    Standard = 0,
    High = 1,
    Critical = 2,
}

/// Policy defining multi-sig attestation requirements per sensitivity level.
#[contracttype]
#[derive(Clone)]
pub struct AttestationPolicy {
    pub sensitivity: CredentialSensitivity,
    /// Minimum number of co-signatures required.
    pub threshold: u32,
    /// Seconds within which all signatures must be collected (default 7 days).
    pub window_seconds: u64,
}

/// The type of zero-knowledge claim being verified.
#[contracttype]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u32)]
pub enum ClaimType {
    HasDegree = 1,
    HasLicense = 2,
    HasEmploymentHistory = 3,
    HasCertification = 4,
    HasResearchPublication = 5,
}

/// Token representation returned by the SBT registry.
#[contracttype]
#[derive(Clone)]
pub struct SoulboundToken {
    pub id: u64,
    pub owner: Address,
    pub credential_id: u64,
    pub metadata_uri: Bytes,
    pub version: u32,
    /// Issue #992: If set, this SBT has been upgraded to another SBT ID.
    /// Old SBT cannot be verified independently when upgraded.
    pub upgraded_to: Option<u64>,
    /// Issue #1275: Optional co-owner (e.g. an organization) for credentials
    /// issued jointly to an individual and an organization.
    pub co_owner: Option<Address>,
}

