        let names: Vec<soroban_sdk::String> = (0..5)
            .map(|i| String::from_str(&env, &format!("V{}", i + 1)))
            .collect();
        let desc = String::from_str(&env, "desc");

        client.register_credential_type(&admin, &1u32, &names.get(0).unwrap(), &desc, &None);
